(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zh"] = {"ui":{"skip":"跳到正文","back":"← 返回 AI-gile","lang.button":"语言：{name}","lang.dialog":"选择语言","lang.search":"搜索语言","lang.none":"没有匹配的语言","lang.notYet":"{name} 还没有翻译","theme.aria":"在浅色和深色主题之间切换","theme.toLight":"切换到浅色主题","theme.toDark":"切换到深色主题","index.title":"AI-gile：你的 AI 开发团队，都在一块看板上","index.description":"AI-gile 是给 AI 编程团队用的看板。你睡觉时他们在干活；你只会收到一小堆需要决定、测试和验收的事。","hero.logoAlt":"AI-gile 看板图标","hero.h1.html":"你的 AI 开发团队，都在一块&nbsp;看板上。","hero.alpha":"🐣 封闭预 Alpha","hero.alphaTitle":"还早，也没做完：感谢你来试用！","hero.lede":"你睡觉时他们在开发。醒来只有一小堆事：几个问题，几样要测试的东西，一两颗紫色钻石。点一点，验收，接着去喝你的咖啡。","dl.windows":"Windows 应用","dl.browser":"在浏览器中运行","dl.soon":"即将推出","dl.notify":"🔔 开放时通知我","dl.notifySmall":"Alpha 或 Beta","hero.secondary":"敏捷开发，但团队从不需要站会咖啡。（不过他们还是照开站会。）","pitch.h2":"想用几个字介绍 AI-gile，都行","pitch.lede":"选一个长度，从一个字到 144 个字。每个长度都是专门为这个篇幅写的一段介绍。拖动滑块，或用方向键。","pitch.rangeLabel":"字数","pitch.dice":"🎲 换一个版本","pitch.words.one":"{n} 个词","pitch.words.other":"{n} 个词","pitch.letters.one":"{n} 个字母","pitch.letters.other":"{n} 个字母","pitch.chars.one":"{n} 个字","pitch.chars.other":"{n} 个字","count.line.html.one":"看板上现在有 {n} 张卡片","count.line.html.other":"看板上现在有 {n} 张卡片","features.aria":"它能做什么","f.pile.h":"给你的一小堆","f.pile.html":"<b>待你处理</b>汇集了所有项目里等你的事：问题、要测试的东西、只有人能做的任务。你的队列会告诉你下一件是什么、要花多久。","f.sleep.h":"你睡觉时也在干活的团队","f.sleep.p":"每个项目都有一位负责人和一队 AI 智能体。在卡片上留言，团队就会醒来干活，再带着疲惫的人也能照着做的步骤交还给你。","f.tester.h":"先由 AI 测试员检查","f.tester.p":"东西送到你面前之前，测试员会在应用的副本里照着步骤操作，并附上截图说明看到了什么。通过的快速翻一翻，一键验收。","f.proof.h":"有证据，不画饼","f.proof.p":"每次交付都会列出改了什么：文件、差异、截图。不用逐个打开应用去确认做完没有。","f.chat.h":"和你的负责人聊天","f.chat.p":"类似 Discord 的侧栏：每个项目一个图标，需要你的事用紫色钻石标出。把想法发给负责人，他们会整理成卡片和计划，并附上“✅ 开始”按钮。","f.tidy.h":"自己保持整洁","f.tidy.p":"相关卡片合并成一张，含糊的标题会被改清楚，用量检查让代码保持精简。要切换的东西更少，要操心的也更少。","f.private.h":"归你所有，就在你的电脑上","f.private.li1":"看板运行在你自己的电脑上，只听你的。","f.private.li2":"人与人之间的私信采用端到端加密。","f.private.li3":"没有账号，没有跟踪器，没有 Cookie。","f.lang.h":"说你的语言","f.lang.p":"支持 120 多种语言，从荷兰语、威尔士语、日语，到海盗腔、尤达腔和克林贡语，开发相关的词还能一键切回英文。","tl.aria":"从第一次对话到路线图的时间线","tl.h2":"从第一次聊天到接下来的计划","tl.lede":"真实的日期和时间，按你自己的时区显示。今天之后就是计划，不承诺具体日期。","tl.today":"今天","tl.planned":"计划中","tl.cards.one":"{n} 张卡片","tl.cards.other":"{n} 张卡片","join.h2":"一起来玩","join.lede":"AI-gile 由一个小小的人类和一大群耐心的智能体打造。目前不公开，只在朋友间封闭内测。开放时想试试吗？","join.btn":"登记兴趣","join.small":"只会给你发邮件，别无其他","footer.tag":"AI-gile。没有跟踪器，没有 Cookie，没有站会咖啡。","footer.licence":"商用许可","footer.status":"状态","form.sending":"发送中…","form.failed":"没成功：请稍后再试。","form.offline":"连不上 AI-gile：请稍后再试。","interest.title":"AI-gile：Alpha 开放时通知我","interest.description":"留下邮箱，AI-gile 的封闭 Alpha 或 Beta 开放时我们会告诉你。","interest.h1":"🔔 开放时通知我","interest.lede":"AI-gile 正处于封闭预 Alpha 阶段。留下邮箱，等有你的位置时，我们只写一封信。","interest.email":"你的邮箱","interest.which":"哪种测试？","interest.alpha":"封闭 Alpha：早期、粗糙、变化多","interest.beta":"Beta：更稳定，更晚","interest.both":"都行，哪个先开就哪个","interest.submit":"把我加入名单","interest.thanks":"谢谢！你已在名单上。","interest.kept":"只会保存你的邮箱和你选的测试，仅用于这份名单。没有新闻邮件，没有跟踪器。","licence.title":"AI-gile：商用许可","licence.description":"要在公司里使用 AI-gile？可以免费申请商用许可。","licence.h1":"📜 商用许可","licence.lede":"想在工作中使用 AI-gile？告诉我们你是谁、做什么。只要做的事有益处，许可就是免费的。","licence.company":"公司","licence.website":"网站","licence.what":"你做什么","licence.how":"它如何帮助世界","licence.email":"邮箱","licence.submit":"申请","licence.thanks":"谢谢！我们会通过邮件回复。","status.title":"AI-gile 状态","status.h1":"AI-gile 状态","status.quiet":"一切平静","status.checking":"检查中…","status.offline":"暂时连不上状态服务（正在重试）","status.updated":"更新于{ago}","status.justNow":"刚刚","status.min":"{n} 分钟前","status.hours":"{n} 小时前","status.days":"{n} 天前","live.h2":"实时看它是怎么建起来的","live.caption":"每张卡片都是隐藏的：你看到的是工作的样子，而不是文字。","live.watching.one":"实时：{n} 人正在看","live.watching.other":"实时：{n} 人正在看","live.offline":"实时看板正在稍作休息，请稍后再来看看。","live.cols":"Backlog|待办|进行中|团队检查中|待你测试|交给团队|已完成","live.last.now":"最近一张卡片刚刚移动","live.last.min.one":"最近一张卡片在 {n} 分钟前移动","live.last.min.other":"最近一张卡片在 {n} 分钟前移动","live.last.hour.one":"最近一张卡片在 {n} 小时前移动","live.last.hour.other":"最近一张卡片在 {n} 小时前移动","live.last.day.one":"最近一张卡片在 {n} 天前移动","live.last.day.other":"最近一张卡片在 {n} 天前移动"},"lines":{"unit":"chars","sizes":[{"n":1,"texts":["看板。","机器人。","放手。"]},{"n":2,"texts":["机器人看板。","智能体，有序。","想法，成真。"]},{"n":3,"texts":["给机器人的看板。","想法变成功能。","免费智能体看板。"]},{"n":5,"texts":["由智能体运转的看板。","你写卡片，智能体来做。","免费、本地、有测试，还有点傻气。"]},{"n":8,"texts":["一块免费的看板，AI 智能体在上面干活。","写下想法，智能体去做，最后由你验收。","给一个人类和一群耐心机器人用的敏捷。"]},{"n":13,"texts":["一块在你电脑上的看板，AI 智能体会自己来领卡片干活。","写下一个想法，一队智能体动手做，再由测试员检查一遍。","免费，没有账号，没有跟踪器：一块看板，几个机器人，你说了算。"]},{"n":21,"texts":["AI-gile 是一块用来和 AI 编程智能体合作的看板。卡片由它们去领，测试和验收则交给你来做。","每个项目都有一位负责人和一队 AI 智能体。你在任意一张卡片上留言，团队就会开始动手干活。","这是一块免费的个人待办看板，就运行在你自己的电脑上。干活的是机器人，点头说好的人是你。"]},{"n":34,"texts":["你把想法放到看板上，一队 AI 智能体把它们做成能用的功能，自己测试一遍，再附上试用步骤交还给你。你没点头之前，没有任何东西算完成。","AI-gile 是一块自制的看板，Rich 在如今被它管理的智能体们的大力帮助下造出了它。它免费，运行在你的电脑上，只分享给朋友，从不出售。","想象一块普通的看板，列从待办排到已完成，只不过卡片是由 AI 智能体来领的。它们会汇报进度，卡住时会提问，而且永远等着你点头同意。"]},{"n":55,"texts":["AI-gile 是一块团队由 AI 智能体组成的看板。每个项目都有一位负责规划的负责人，和几位动手开发的助手。功能做好后，AI 测试员会先试用并截图，然后才放进你的那一小堆。你可以验收，也可以留言，他们就会返工重做。","它起初只是一个人用来同时盯着许多 AI 编程会话的办法，后来慢慢长成了一块像样的看板。它运行在你的电脑上，不需要账号，也没有跟踪器。朋友和好奇的人都可以免费用。它还没做完，所以难免有些毛糙，偶尔也会有小意外。","说句实话：想法还得你来想，结果还得你来看。AI-gile 管的是中间所有的事：让卡片井然有序，你一留言就叫醒该醒的智能体，清楚展示究竟改了什么，再把这一切收进给你的一小堆里。另外它在你的电脑上运行，不要账号，也没有任何跟踪器，完全免费，你想怎么用都行，随时可以停。"]},{"n":89,"texts":["AI-gile 是一块免费的看板，运行在你自己的电脑上。每个项目里干活的不是人，而是一队 AI 智能体：负责人把你的想法整理成卡片和计划，助手则按优先级领取卡片。做好之后，AI 测试员会照着测试步骤操作，并给你看它看到了什么。接着它会放进标着待你处理的那一小堆里等你。你可以验收，也可以留言让团队再来一轮。没有你点头，任何东西都到不了已完成。","有几个你也许想不到的功能。夜班守望会在你睡觉时给待办列补货，专挑不需要你回答的卡片。用量计数器会显示智能体今天和本周用了多少，省用模式则让它们停止消耗。你可以给朋友发消息，私信采用端到端加密。看板支持大约 120 种语言，包括荷兰语、弗拉芒语、海盗腔和克林贡语。这一切一分钱都不收，也没有人想把它卖给你。它运行在你自己的电脑上，不需要账号，也没有跟踪器和 Cookie，数据始终留在你手里。","AI-gile 是一个小小的个人项目，不是公司。Rich 想同时照看好几个 AI 编程项目，又不想挨个打开应用去查看，于是他和智能体们一起造了这块看板，又用这块看板造出了它自己的其余部分。它处于封闭预 Alpha 阶段，意思是对少数几位朋友来说，大体上能用。这里没有价格页，没有新闻邮件，也没有增长计划。如果你觉得有用，等它再开放一些，可以申请试用。"]},{"n":144,"texts":["AI-gile 是给一个人类和许多 AI 智能体用的看板。它运行在你自己的电脑上，完全免费。你添加项目，每个项目都会有一位负责人和一支小团队。你可以和负责人聊天，有点像 Discord，把想法讲给他听；他会把想法整理成卡片和计划，然后等你点下开始。团队按优先级逐张处理卡片，用的是一套专门为语言模型设计的简单命令行。任何东西回到你手里之前，AI 测试员都会在应用的副本里照着步骤操作，并附上截图。做完的工作连同改动的文件和差异，一起落进你的那一小堆。你可以验收，也可以留下一条评论，团队就会醒来再试一次。只有你能把卡片挪到已完成。","大致说说和 AI-gile 度过的一天。傍晚你留下几条评论：这个按钮位置不对，那个列表该排个序，能不能加个深色模式。然后你去睡觉。智能体们读完评论，动手修改，测试，再交还给你。如果待办列空了，夜班守望就从积压清单里补货，挑那些不需要你回答的卡片。早上你面前只有一小堆：几个问题，几样要试的东西，每样都有睡眼惺忪的人也能照做的步骤，还有一张证明它能用的截图。你一路点过去，好的验收，其余的退回，写一句话告诉它们哪里不对就行。用量计数器会告诉你这一切花了多少，节俭的几周还有省用模式可以开。每个项目各有各的负责人，各有各的团队，互不打扰。然后你去吃早餐，这一步智能体暂时还帮不上忙。","先说说 AI-gile 不是什么。它不是创业公司，不对外出售，也没有人在收集你的数据。它是一块免费的看板，运行在你的电脑上，没有账号，没有跟踪器，也没有 Cookie。它是什么呢：一个整洁的地方，能一眼看到所有 AI 编程项目，一队智能体负责做卡片，决定则由你来下。它会把相关的卡片合并，把含糊的标题改清楚，还留意代码是不是保持精简。它支持大约 120 种语言，从荷兰语、弗拉芒语到海盗腔和克林贡语。朋友之间可以私下发消息，而且是加密的。它由 Rich 和一大群耐心的智能体打造，多半是靠它自己来完成的。它仍处于封闭预 Alpha 阶段，有些地方还很粗糙。如果听起来有趣，客气地问一问，也许你能提前进来。"]}],"quips":{"1":"就一个词。够大胆。也许太大胆了。","3":"三个词。已经比大多数产品页更诚实了。","8":"八个词。还是比一次站会短。","21":"顺便说一句，这些长度是故事点数。那当然。","55":"五十五个词。你读这段的工夫，有两张卡片做完了。","144":"这是最长的一版。没有 233 了。智能体已经去睡了。"}},"timeline":{"first-idea.name":"最初的想法","first-idea.line":"第一次对话，那时还没有任何代码。","first-board.name":"第一块看板","first-board.line":"一块记录自己如何被造出来的看板：卡片、列、拖放、项目。","team-roles.name":"团队与角色","team-roles.line":"智能体档案、团队模板、空间，以及谁负责什么。","install.name":"安装与发布","install.line":"朋友也能安装的压缩包、自动更新、渠道和回滚。","usage-saver.name":"用量节省","usage-saver.line":"衡量每次运行的花费，保持代码精简，省下你的额度。","friends.name":"好友与分享","friends.line":"私信、加扰中继、邀请、角色和共享项目。","languages.name":"语言","languages.line":"所有界面文字都放进语言文件，先有荷兰语和弗拉芒语。","ai-tester.name":"AI 测试员","ai-tester.line":"每次交付先由测试员检查，并展示它看到的内容。","website.name":"网站","website.line":"aigile.lol、预告页和这条时间线。","streaming.name":"聊天与直播","streaming.line":"Discord、Twitch、OBS、主播模式、GIF 和表情。","no-ai.name":"无 AI 版","no-ai.line":"给不用 AI 写代码的人用的看板，以及公开看板。","night-watch.name":"夜班守望","night-watch.line":"守夜人和 Scrum Master 在你睡觉时盯着团队干活。","p-more.name":"其他一切","p-more.line":"还在排队等轮到的小想法。","p-android.name":"手机与安卓","p-android.line":"先用手机访问你的看板，再做原生安卓应用。","p-release.name":"Alpha 及以后","p-release.line":"封闭 Alpha、正式上线的网站，然后是 Beta。","p-languages.name":"更多语言","p-languages.line":"超过一百种语言，还有给学习者的沉浸模式。","p-engines.name":"更多 AI 引擎","p-engines.line":"为每个智能体选择 Claude、Codex 或 Gemini。","p-pro.name":"专业实践","p-pro.line":"风险标签、合并关卡、事故卡片和护栏。","p-self.name":"照顾你自己","p-self.line":"疲惫模式、自我关怀提醒和 4:20。","p-servers.name":"服务器与规模","p-servers.line":"全局服务器设置、角色，以及为增长做的规划。","p-livestream.name":"直播附加功能","p-livestream.line":"Twitch 聊天、自定义表情和公开的直播视图。"}};
